#!/bin/bash
# S-Mamba on ETTm1: input 96, horizons 96 192 336 720; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/ETT/S_Mamba_ETTm1.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/ETT/S_Mamba_ETTm1.sh   one seed on the CPU
# Results: output/long_term_forecast/ETTm1.tsv (one row per run); checkpoints: temp/checkpoints/ETTm1/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root ETTm1.csv)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 96: scripts/benchmark/official/S_Mamba/ETT/S_Mamba_ETTm1.sh
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model S_Mamba \
    --des ETTm1_96_S_Mamba \
    --seed "$seed" \
    --root_path "$root" \
    --data_path ETTm1.csv \
    --data ETTm1 \
    --model_id ETTm1_96_96 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 96 \
    --enc_in 7 \
    --dec_in 7 \
    --c_out 7 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --e_layers 2 \
    --d_model 256 \
    --d_state 2 \
    --learning_rate 0.00005 \
    --d_ff 256 \
    $EXTRA_ARGS
done

